        printUInt32(O, Value);

        if (MI->csh->detail) {
                MI->flat_insn->detail->ppc.operands[MI->flat_insn->detail->ppc.op_count].type = PPC_OP_IMM;
                MI->flat_insn->detail->ppc.operands[MI->flat_insn->detail->ppc.op_count].imm = Value;
                MI->flat_insn->detail->ppc.op_count++;
        }
}

